RunId = str


# A path relative to the repository root: . for the root, or segments of letters, digits and . _ @ +
# = , - joined by single slashes, with an optional trailing slash for a directory. No leading slash,
# no empty segment, and no segment that is . or .. A path outside the repository starts with a
# placeholder segment such as <sandbox> or <scratch> (private paths are never recorded); GATE-runs
# does not hash those.
RunPath = str


class RunInput(TypedDict):
    """A file the run read, located by a repository path, a URL or a file name, with its SHA-256 at
    execution time. A directory's sha256 is a manifest hash, named by sha256_method.
    """
    # The file's path in the repository.
    path: NotRequired[RunPath]
    # Where the file was downloaded from.
    url: NotRequired[str]
    # The file's name inside an archive or image, when it has no repository path.
    name: NotRequired[str]
    # The downloaded file's name.
    file: NotRequired[str]
    # SHA-256 of the file's bytes when the run read it.
    sha256: Sha256
    # The file's size in bytes.
    bytes: NotRequired[int]
    # What the run used the file for: spec, config, script, harness, fixture.
    role: NotRequired[str]


class RunOutput(TypedDict):
    """A file that holds output of the run, with its SHA-256 and size. GATE-runs fails when a file
    under runs/ no longer matches.
    """
    # The file's path in the repository.
    path: RunPath
    # SHA-256 of the file's bytes.
    sha256: Sha256
    # The file's size in bytes.
    bytes: int
    # What the file holds: a log, a trace, a report.
    kind: NotRequired[str]


class RunConfig(TypedDict):
    """One configuration of a run with several. It repeats only the fields that differ from the top
    level.
    """
    # The configuration's name, unique within the run.
    id: str
    # What this configuration shows.
    purpose: NotRequired[str]
    # As origin at the top level, for this configuration.
    origin: NotRequired[Literal["recorded", "imported"]]
    engine: NotRequired[str]
    version: NotRequired[str]
    binary_sha256: NotRequired[Sha256 | None]
    image: NotRequired[str | None]
    started_at: NotRequired[Instant | LocalDate | None]
    duration_s: NotRequired[float | None]
    # The exact command line of this configuration; empty when the configuration executed nothing (a
    # file hashed, not run).
    argv: NotRequired[list[str] | None]
    inputs: NotRequired[list[RunInput]]
    budget: NotRequired[dict[str, Any]]
    exit_code: NotRequired[int | None]
    verdict_lines: NotRequired[list[str]]
    # Output files of this configuration, as output records or as paths of files listed at the top
    # level.
    outputs: NotRequired[list[RunPath | RunOutput]]


# A named check on the run's outputs and whether it passed.
RunCheck = TypedDict(
    "RunCheck",
    {
        "id": str,
        "pass": bool,
    },
)


class RunUnrecorded(TypedDict):
    """A core field that is null because the execution did not record it."""
    # The field's name, such as argv or binary_sha256.
    field: str
    # Why the value is missing, and how it could be recovered.
    reason: Prose


# statespace run record, version 1. One recorded tool execution in the runs registry,
# runs/<RUN-id>.json (spine section 9.5; ARCHITECTURE.md section 9.1). Copy cites it as
# {{run:RUN-id}} and documents as [X RUN-id]; GATE-numbers requires those citations and GATE-runs
# resolves them and checks this record's integrity. A record is identified by its path, so it
# carries no schema tag. Field names are snake_case, the form every W0 record uses; spine section
# 9.5 writes the same fields in camelCase (binarySha256, inputSha256, recordedAt), and
# runs/README.md maps the two. Every value is copied from the execution's own output or computed
# from files on disk, never typed from memory. A value that the execution did not record is null,
# and an imported record (origin imported) names each such field in unrecorded with the reason. The
# root stays open: an engine adds its own fields (checks, values, probes and so on) beside the core,
# which this schema types.
RunRecord = TypedDict(
    "RunRecord",
    {
        "id": RunId,
        "title": Prose,
        "task": NotRequired[str],
        "origin": NotRequired[Literal["recorded", "imported"]],
        "records": NotRequired[Prose],
        "engine": str,
        "version": str,
        "version_string": NotRequired[str],
        "binary": str | None,
        "binary_sha256": Sha256 | None,
        "image": str | None,
        "recorded_at": Instant,
        "started_at": Instant | LocalDate | None,
        "duration_s": float | None,
        "argv": list[str] | list[list[str]] | None,
        "inputs": list[RunInput],
        "budget": RunRecordBudget,
        "exit_code": int | None,
        "verdict_lines": list[str],
        "outputs": list[RunOutput],
        "values": NotRequired[dict[str, Any]],
        "environment": RunRecordEnvironment,
        "configs": NotRequired[list[RunConfig]],
        "primary_config": NotRequired[str],
        "checks": NotRequired[list[RunCheck]],
        "pass": NotRequired[bool],
        "ttl_days": NotRequired[int],
        "unrecorded": NotRequired[list[RunUnrecorded]],
        "notes": list[Prose],
    },
)


# Record types by the value of their `schema` field.
RECORD_TYPES: dict[str, type] = {
    "statespace/claim@1": Claim,
    "statespace/ir@1": IR,
    "statespace/receipt@1": Receipt,
}

